package com.team15.tripplanning.bookingservice.feature.settlement;

import com.team15.tripplanning.bookingservice.dto.SettlementProcessRequest;
import com.team15.tripplanning.bookingservice.dto.SettlementResultDTO;
import com.team15.tripplanning.bookingservice.messaging.publisher.PaymentEventPublisher;
import com.team15.tripplanning.bookingservice.model.Settlement;
import com.team15.tripplanning.bookingservice.model.mongo.PaymentAuditEvent;
import com.team15.tripplanning.bookingservice.repository.PaymentAuditEventRepository;
import com.team15.tripplanning.bookingservice.repository.SettlementRepository;
import com.team15.tripplanning.contracts.events.PaymentCompletedEvent;
import com.team15.tripplanning.contracts.events.PaymentFailedEvent;
import com.team15.tripplanning.bookingservice.security.JwtService;
import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class SettlementService {

    private final SettlementRepository settlementRepository;
    private final PaymentAuditEventRepository paymentAuditEventRepository;
    private final PaymentEventPublisher paymentEventPublisher;
    private final JwtService jwtService;

    public SettlementService(SettlementRepository settlementRepository,
                             PaymentAuditEventRepository paymentAuditEventRepository,
                             PaymentEventPublisher paymentEventPublisher,
                             JwtService jwtService) {
        this.settlementRepository = settlementRepository;
        this.paymentAuditEventRepository = paymentAuditEventRepository;
        this.paymentEventPublisher = paymentEventPublisher;
        this.jwtService = jwtService;
    }

    @Transactional
    public SettlementResultDTO processSettlement(SettlementProcessRequest request, HttpServletRequest httpRequest) {
        if (request == null || request.getItineraryId() == null || request.getUserId() == null || request.getAmount() == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "itineraryId, userId, and amount are required");
        }

        Settlement settlement = settlementRepository.findByItineraryIdForUpdate(request.getItineraryId())
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND,
                        "Saga has not yet completed for this itinerary; cannot settle"));

        if (settlement.getStatus() == Settlement.SettlementStatus.PROCESSING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Settlement already in flight");
        }
        if (settlement.getStatus() == Settlement.SettlementStatus.COMPLETED) {
            return SettlementResultDTO.from(
                    settlement.getId(),
                    settlement.getItineraryId(),
                    settlement.getUserId(),
                    settlement.getAmount(),
                    settlement.getStatus().name(),
                    settlement.getSettledAt(),
                    settlement.getFailureReason()
            );
        }
        if (settlement.getStatus() == Settlement.SettlementStatus.FAILED
                || settlement.getStatus() == Settlement.SettlementStatus.REFUNDED) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Settlement already finalized");
        }

        Long jwtUserId = extractUserId(httpRequest);
        if (jwtUserId == null || !jwtUserId.equals(request.getUserId()) || !jwtUserId.equals(settlement.getUserId())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Not authorized for this settlement");
        }

        if (settlement.getAmount() == null || settlement.getAmount().compareTo(request.getAmount()) != 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Amount mismatch");
        }

        int moved = settlementRepository.updateStatusIfMatches(
                settlement.getId(),
                Settlement.SettlementStatus.PROCESSING,
                Settlement.SettlementStatus.PENDING
        );
        if (moved == 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Settlement already in flight");
        }

        boolean approved = request.getAmount().compareTo(BigDecimal.ZERO) > 0;
        if (approved) {
            settlement.setStatus(Settlement.SettlementStatus.COMPLETED);
            settlement.setSettledAt(LocalDateTime.now());
            settlementRepository.save(settlement);

            Map<String, Object> auditDetails = new HashMap<>();
            auditDetails.put("action", "SETTLEMENT_COMPLETED");
            auditDetails.put("settlementId", settlement.getId());
            auditDetails.put("itineraryId", settlement.getItineraryId());
            auditDetails.put("userId", settlement.getUserId());
            auditDetails.put("amount", settlement.getAmount().doubleValue());
            paymentAuditEventRepository.save(new PaymentAuditEvent(auditDetails));

            paymentEventPublisher.publishPaymentCompleted(
                    new PaymentCompletedEvent(settlement.getId(), settlement.getItineraryId(), settlement.getAmount())
            );

            return SettlementResultDTO.from(
                    settlement.getId(),
                    settlement.getItineraryId(),
                    settlement.getUserId(),
                    settlement.getAmount(),
                    settlement.getStatus().name(),
                    settlement.getSettledAt(),
                    settlement.getFailureReason()
            );
        }

        settlement.setStatus(Settlement.SettlementStatus.FAILED);
        settlement.setSettledAt(LocalDateTime.now());
        settlement.setFailureReason("Payment rejected");
        settlementRepository.save(settlement);

        Map<String, Object> auditDetails = new HashMap<>();
        auditDetails.put("action", "SETTLEMENT_FAILED");
        auditDetails.put("settlementId", settlement.getId());
        auditDetails.put("itineraryId", settlement.getItineraryId());
        auditDetails.put("userId", settlement.getUserId());
        auditDetails.put("amount", settlement.getAmount().doubleValue());
        auditDetails.put("reason", settlement.getFailureReason());
        paymentAuditEventRepository.save(new PaymentAuditEvent(auditDetails));

        paymentEventPublisher.publishPaymentFailed(
                new PaymentFailedEvent(settlement.getId(), settlement.getItineraryId(), settlement.getFailureReason())
        );

        return SettlementResultDTO.from(
                settlement.getId(),
                settlement.getItineraryId(),
                settlement.getUserId(),
                settlement.getAmount(),
                settlement.getStatus().name(),
                settlement.getSettledAt(),
                settlement.getFailureReason()
        );
    }

    private Long extractUserId(HttpServletRequest request) {
        String header = request.getHeader("Authorization");
        if (header == null || !header.startsWith("Bearer ")) {
            return null;
        }
        String token = header.substring(7);
        return jwtService.extractUserId(token);
    }
}

package com.team15.tripplanning.bookingservice.messaging.consumer;

import com.team15.tripplanning.bookingservice.messaging.publisher.AmqpConfig;
import com.team15.tripplanning.bookingservice.messaging.publisher.PaymentEventPublisher;
import com.team15.tripplanning.bookingservice.model.Booking;
import com.team15.tripplanning.bookingservice.model.Settlement;
import com.team15.tripplanning.bookingservice.model.Settlement.SettlementStatus;
import com.team15.tripplanning.bookingservice.model.mongo.PaymentAuditEvent;
import com.team15.tripplanning.bookingservice.repository.BookingRepository;
import com.team15.tripplanning.bookingservice.repository.PaymentAuditEventRepository;
import com.team15.tripplanning.bookingservice.repository.SettlementRepository;
import com.team15.tripplanning.contracts.events.ItineraryCancelledEvent;
import com.team15.tripplanning.contracts.events.ItineraryCompletedEvent;
import com.team15.tripplanning.contracts.events.PaymentInitiatedEvent;
import com.team15.tripplanning.contracts.events.PaymentRefundedEvent;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.amqp.rabbit.annotation.RabbitHandler;
import org.springframework.amqp.rabbit.annotation.RabbitListener;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

@Component
@RabbitListener(queues = AmqpConfig.SAGA_QUEUE)
public class ItineraryEventConsumer {

    private final SettlementRepository settlementRepository;
    private final BookingRepository bookingRepository;
    private final PaymentAuditEventRepository paymentAuditEventRepository;
    private final PaymentEventPublisher paymentEventPublisher;

    public ItineraryEventConsumer(SettlementRepository settlementRepository,
                                 BookingRepository bookingRepository,
                                 PaymentAuditEventRepository paymentAuditEventRepository,
                                 PaymentEventPublisher paymentEventPublisher) {
        this.settlementRepository = settlementRepository;
        this.bookingRepository = bookingRepository;
        this.paymentAuditEventRepository = paymentAuditEventRepository;
        this.paymentEventPublisher = paymentEventPublisher;
    }

    @RabbitHandler
    @Transactional
    public void onItineraryCompleted(ItineraryCompletedEvent event) {
        BigDecimal totalAmount = toBigDecimal(bookingRepository.sumConfirmedAmountByItineraryId(event.itineraryId()));
        Settlement settlement = new Settlement();
        settlement.setItineraryId(event.itineraryId());
        settlement.setUserId(event.userId());
        settlement.setAmount(totalAmount);
        settlement.setStatus(SettlementStatus.PENDING);

        try {
            settlement = settlementRepository.save(settlement);
        } catch (DataIntegrityViolationException ex) {
            return; // idempotent: settlement already exists
        }

        Map<String, Object> auditDetails = new HashMap<>();
        auditDetails.put("action", "SETTLEMENT_PENDING");
        auditDetails.put("itineraryId", event.itineraryId());
        auditDetails.put("settlementId", settlement.getId());
        auditDetails.put("userId", event.userId());
        auditDetails.put("amount", totalAmount.doubleValue());
        paymentAuditEventRepository.save(new PaymentAuditEvent(auditDetails));

        paymentEventPublisher.publishPaymentInitiated(
                new PaymentInitiatedEvent(settlement.getId(), event.itineraryId(), totalAmount)
        );
    }

    @RabbitHandler
    @Transactional
    public void onItineraryCancelled(ItineraryCancelledEvent event) {
        Long settlementId = settlementRepository.findByItineraryId(event.itineraryId())
                .map(Settlement::getId)
                .orElse(null);

        List<Booking> bookings = bookingRepository.findByItineraryId(event.itineraryId());
        for (Booking booking : bookings) {
            if (booking.getStatus() == Booking.BookingStatus.PENDING) {
                bookingRepository.updateStatusByIdAndStatus(
                        booking.getId(),
                        Booking.BookingStatus.CANCELLED.name(),
                        Booking.BookingStatus.PENDING.name()
                );
                continue;
            }

            if (booking.getStatus() == Booking.BookingStatus.CONFIRMED) {
                int updated = bookingRepository.updateStatusByIdAndStatus(
                        booking.getId(),
                        Booking.BookingStatus.CANCELLED.name(),
                        Booking.BookingStatus.CONFIRMED.name()
                );
                if (updated == 1) {
                    BigDecimal refundAmount = toBigDecimal(booking.getAmount());
                    Map<String, Object> auditDetails = new HashMap<>();
                    auditDetails.put("action", "REFUNDED");
                    auditDetails.put("bookingId", booking.getId());
                    auditDetails.put("userId", booking.getUserId());
                    auditDetails.put("amount", refundAmount.doubleValue());
                    paymentAuditEventRepository.save(new PaymentAuditEvent(auditDetails));

                    paymentEventPublisher.publishPaymentRefunded(
                            new PaymentRefundedEvent(settlementId, booking.getItineraryId(), refundAmount)
                    );
                }
            }
        }

        settlementRepository.findByItineraryId(event.itineraryId()).ifPresent(settlement -> {
            if (settlement.getStatus() != SettlementStatus.REFUNDED) {
                settlement.setStatus(SettlementStatus.REFUNDED);
                settlement.setSettledAt(LocalDateTime.now());
                settlementRepository.save(settlement);
            }
        });
    }

    private BigDecimal toBigDecimal(Double value) {
        return BigDecimal.valueOf(value != null ? value : 0.0);
    }
}

package com.team15.tripplanning.bookingservice.messaging.publisher;

import org.springframework.amqp.core.Binding;
import org.springframework.amqp.core.BindingBuilder;
import org.springframework.amqp.core.Queue;
import org.springframework.amqp.core.QueueBuilder;
import org.springframework.amqp.core.TopicExchange;
import org.springframework.amqp.rabbit.connection.ConnectionFactory;
import org.springframework.amqp.rabbit.core.RabbitTemplate;
import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;
import org.springframework.amqp.support.converter.MessageConverter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class AmqpConfig {

    public static final String PAYMENT_EXCHANGE = "payment.events";
    public static final String ITINERARY_EXCHANGE = "itinerary.events";
    public static final String SAGA_QUEUE = "payment.saga-listener";
    public static final String SAGA_DLQ = "payment.saga-listener.dlq";
    public static final String SAGA_DLX = "payment.saga-listener.dlx";
    public static final String SAGA_DLQ_ROUTING_KEY = "payment.saga-listener.dlq";

    @Bean
    public TopicExchange paymentExchange() {
        return new TopicExchange(PAYMENT_EXCHANGE);
    }

    @Bean
    public TopicExchange itineraryExchange() {
        return new TopicExchange(ITINERARY_EXCHANGE);
    }

    @Bean
    public TopicExchange sagaDeadLetterExchange() {
        return new TopicExchange(SAGA_DLX);
    }

    @Bean
    public Queue sagaQueue() {
        return QueueBuilder.durable(SAGA_QUEUE)
                .withArgument("x-dead-letter-exchange", SAGA_DLX)
                .withArgument("x-dead-letter-routing-key", SAGA_DLQ_ROUTING_KEY)
                .build();
    }

    @Bean
    public Queue sagaDeadLetterQueue() {
        return QueueBuilder.durable(SAGA_DLQ).build();
    }

    @Bean
    public Binding itineraryCompletedBinding(Queue sagaQueue, TopicExchange itineraryExchange) {
        return BindingBuilder.bind(sagaQueue).to(itineraryExchange).with("itinerary.completed");
    }

    @Bean
    public Binding itineraryCancelledBinding(Queue sagaQueue, TopicExchange itineraryExchange) {
        return BindingBuilder.bind(sagaQueue).to(itineraryExchange).with("itinerary.cancelled");
    }

    @Bean
    public Binding sagaDeadLetterBinding(Queue sagaDeadLetterQueue, TopicExchange sagaDeadLetterExchange) {
        return BindingBuilder.bind(sagaDeadLetterQueue).to(sagaDeadLetterExchange).with(SAGA_DLQ_ROUTING_KEY);
    }

    @Bean
    public MessageConverter jacksonMessageConverter() {
        return new Jackson2JsonMessageConverter();
    }

    @Bean
    public RabbitTemplate rabbitTemplate(ConnectionFactory connectionFactory, MessageConverter messageConverter) {
        RabbitTemplate rabbitTemplate = new RabbitTemplate(connectionFactory);
        rabbitTemplate.setMessageConverter(messageConverter);
        return rabbitTemplate;
    }
}

package com.team15.tripplanning.bookingservice.messaging.publisher;

import com.team15.tripplanning.contracts.events.PaymentCompletedEvent;
import com.team15.tripplanning.contracts.events.PaymentFailedEvent;
import com.team15.tripplanning.contracts.events.PaymentInitiatedEvent;
import com.team15.tripplanning.contracts.events.PaymentRefundedEvent;
import org.springframework.amqp.rabbit.core.RabbitTemplate;
import org.springframework.stereotype.Component;

@Component
public class PaymentEventPublisher {

    private final RabbitTemplate rabbitTemplate;

    public PaymentEventPublisher(RabbitTemplate rabbitTemplate) {
        this.rabbitTemplate = rabbitTemplate;
    }

    public void publishPaymentInitiated(PaymentInitiatedEvent event) {
        rabbitTemplate.convertAndSend(AmqpConfig.PAYMENT_EXCHANGE, "payment.initiated", event);
    }

    public void publishPaymentCompleted(PaymentCompletedEvent event) {
        rabbitTemplate.convertAndSend(AmqpConfig.PAYMENT_EXCHANGE, "payment.completed", event);
    }

    public void publishPaymentFailed(PaymentFailedEvent event) {
        rabbitTemplate.convertAndSend(AmqpConfig.PAYMENT_EXCHANGE, "payment.failed", event);
    }

    public void publishPaymentRefunded(PaymentRefundedEvent event) {
        rabbitTemplate.convertAndSend(AmqpConfig.PAYMENT_EXCHANGE, "payment.refunded", event);
    }
}

package com.team15.tripplanning.bookingservice.model;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.PrePersist;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "settlements")
public class Settlement {

    public enum SettlementStatus {
        PENDING,
        PROCESSING,
        COMPLETED,
        FAILED,
        REFUNDED
    }

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "itinerary_id", nullable = false, unique = true)
    private Long itineraryId;

    @Column(name = "user_id", nullable = false)
    private Long userId;

    @Column(nullable = false, precision = 10, scale = 2)
    private BigDecimal amount;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private SettlementStatus status = SettlementStatus.PENDING;

    @Column(name = "created_at", nullable = false, updatable = false, columnDefinition = "TIMESTAMP DEFAULT CURRENT_TIMESTAMP")
    private LocalDateTime createdAt;

    @Column(name = "settled_at")
    private LocalDateTime settledAt;

    @Column(name = "failure_reason", length = 255)
    private String failureReason;

    public Settlement() {
    }

    @PrePersist
    public void prePersist() {
        if (createdAt == null) {
            createdAt = LocalDateTime.now();
        }
        if (status == null) {
            status = SettlementStatus.PENDING;
        }
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getItineraryId() {
        return itineraryId;
    }

    public void setItineraryId(Long itineraryId) {
        this.itineraryId = itineraryId;
    }

    public Long getUserId() {
        return userId;
    }

    public void setUserId(Long userId) {
        this.userId = userId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public SettlementStatus getStatus() {
        return status;
    }

    public void setStatus(SettlementStatus status) {
        this.status = status;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(LocalDateTime createdAt) {
        this.createdAt = createdAt;
    }

    public LocalDateTime getSettledAt() {
        return settledAt;
    }

    public void setSettledAt(LocalDateTime settledAt) {
        this.settledAt = settledAt;
    }

    public String getFailureReason() {
        return failureReason;
    }

    public void setFailureReason(String failureReason) {
        this.failureReason = failureReason;
    }
}

package com.team15.tripplanning.bookingservice.repository;

import com.team15.tripplanning.bookingservice.model.Booking;
import java.time.LocalDateTime;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

@Repository
public interface BookingRepository extends JpaRepository<Booking, Long> {

    List<Booking> findByUserId(Long userId);
    List<Booking> findByItineraryId(@Param("itineraryId") Long itineraryId);
    List<Booking> findByStatus(Booking.BookingStatus status);

    @Query(value = """
            SELECT b.id, b.amount, b.status, i.title AS itinerary_title
            FROM bookings b
            LEFT JOIN itineraries i ON i.id = b.itin_id
            WHERE b.user_id = :userId
            """, nativeQuery = true)
    List<Object[]> findBookingsWithItineraryTitleByUser(@Param("userId") Long userId);

    @Modifying
    @Transactional
    @Query(value = "UPDATE bookings SET status = :status WHERE id = :id", nativeQuery = true)
    int updateStatusById(@Param("id") Long id, @Param("status") String status);

    @Query("""
            SELECT
                COALESCE(SUM(CASE WHEN b.status = 'CONFIRMED' THEN b.amount ELSE 0 END), 0),
                COUNT(CASE WHEN b.status = 'CONFIRMED' THEN 1 END),
                COALESCE(SUM(CASE WHEN b.status = 'CANCELLED' THEN b.amount ELSE 0 END), 0),
                COUNT(CASE WHEN b.status = 'CANCELLED' THEN 1 END)
            FROM Booking b
            WHERE b.createdAt BETWEEN :startDate AND :endDate
            """)
    Object[] getRevenueStats(LocalDateTime startDate, LocalDateTime endDate);

    @Query("""
            SELECT b FROM Booking b
            WHERE b.status = :status
              AND b.createdAt BETWEEN :startDateTime AND :endDateTime
            ORDER BY b.createdAt DESC
            """)
    List<Booking> searchBookings(
            @Param("status") Booking.BookingStatus status,
            @Param("startDateTime") LocalDateTime startDateTime,
            @Param("endDateTime") LocalDateTime endDateTime
    );

    List<Booking> findByCreatedAtBetweenOrderByCreatedAtDesc(
            LocalDateTime startDateTime,
            LocalDateTime endDateTime
    );

    @Query("""
            SELECT b.type, SUM(b.amount)
            FROM Booking b
            WHERE b.userId = :userId AND b.status = 'CONFIRMED'
            GROUP BY b.type
            """)
    List<Object[]> getBookingSummaryByUser(@Param("userId") Long userId);

    @Query(value = "SELECT status FROM itineraries WHERE id = :itineraryId", nativeQuery = true)
    String getItineraryStatus(@Param("itineraryId") Long itineraryId);

    @Query(value = "SELECT COUNT(*) FROM itineraries WHERE id = :itineraryId", nativeQuery = true)
    int countItineraryById(@Param("itineraryId") Long itineraryId);

    @Query(value = "SELECT user_id FROM itineraries WHERE id = :itineraryId", nativeQuery = true)
    Long getItineraryUserId(@Param("itineraryId") Long itineraryId);

    @Query(value = "SELECT COUNT(*) FROM users WHERE id = :userId", nativeQuery = true)
    int countUserById(@Param("userId") Long userId);

    // S5-F10
    @Query(value = """
        SELECT
            d.id                                                          AS destinationId,
            d.name                                                        AS destinationName,
            COALESCE(SUM(b.amount), 0)                                    AS totalRevenue,
            COALESCE(SUM(
                CAST(COALESCE(
                    NULLIF(b.booking_details->>'seasonalSurcharge', ''),
                    '0'
                ) AS NUMERIC)
            ), 0)                                                         AS surchargeRevenue,
            COALESCE(SUM(b.amount), 0) - COALESCE(SUM(
                CAST(COALESCE(
                    NULLIF(b.booking_details->>'seasonalSurcharge', ''),
                    '0'
                ) AS NUMERIC)
            ), 0)                                                         AS baseRevenue,
            COUNT(CASE WHEN CAST(COALESCE(
                NULLIF(b.booking_details->>'seasonalSurcharge', ''),
                '0'
            ) AS NUMERIC) > 0 THEN 1 END)                                AS peakBookingCount,
            COUNT(CASE WHEN CAST(COALESCE(
                NULLIF(b.booking_details->>'seasonalSurcharge', ''),
                '0'
            ) AS NUMERIC) = 0 THEN 1 END)                                AS offPeakBookingCount
        FROM bookings b
        JOIN itineraries i ON i.id = b.itin_id
        JOIN destinations d ON d.id = i.destination_id
        WHERE b.status = 'CONFIRMED'
          AND b.created_at >= :startDate
          AND b.created_at <= :endDate
        GROUP BY d.id, d.name
        ORDER BY SUM(b.amount) DESC
        """, nativeQuery = true)
    List<Object[]> getRevenueByDestinationAndSeason(
            @Param("startDate") LocalDateTime startDate,
            @Param("endDate") LocalDateTime endDate
    );

    @Query(value = """
    SELECT i.id, i.status, i.start_date
    FROM itineraries i
    WHERE i.id = :itineraryId
    """, nativeQuery = true)
    Object[] findItineraryRefundInfoRaw(@Param("itineraryId") Long itineraryId);
}

package com.team15.tripplanning.bookingservice.repository;

import com.team15.tripplanning.bookingservice.model.Booking;
import java.time.LocalDateTime;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

@Repository
public interface BookingRepository extends JpaRepository<Booking, Long> {

    List<Booking> findByUserId(Long userId);
    List<Booking> findByItineraryId(@Param("itineraryId") Long itineraryId);
    List<Booking> findByStatus(Booking.BookingStatus status);


    @Modifying
    @Transactional
    @Query(value = "UPDATE bookings SET status = :status WHERE id = :id", nativeQuery = true)
    int updateStatusById(@Param("id") Long id, @Param("status") String status);

    @Modifying
    @Transactional
    @Query(value = "UPDATE bookings SET status = :newStatus WHERE id = :id AND status = :expectedStatus", nativeQuery = true)
    int updateStatusByIdAndStatus(
            @Param("id") Long id,
            @Param("newStatus") String newStatus,
            @Param("expectedStatus") String expectedStatus
    );

    @Query("""
            SELECT
                COALESCE(SUM(CASE WHEN b.status = 'CONFIRMED' THEN b.amount ELSE 0 END), 0),
                COUNT(CASE WHEN b.status = 'CONFIRMED' THEN 1 END),
                COALESCE(SUM(CASE WHEN b.status = 'CANCELLED' THEN b.amount ELSE 0 END), 0),
                COUNT(CASE WHEN b.status = 'CANCELLED' THEN 1 END)
            FROM Booking b
            WHERE b.createdAt BETWEEN :startDate AND :endDate
            """)
    Object[] getRevenueStats(LocalDateTime startDate, LocalDateTime endDate);

    @Query("""
            SELECT b FROM Booking b
            WHERE b.status = :status
              AND b.createdAt BETWEEN :startDateTime AND :endDateTime
            ORDER BY b.createdAt DESC
            """)
    List<Booking> searchBookings(
            @Param("status") Booking.BookingStatus status,
            @Param("startDateTime") LocalDateTime startDateTime,
            @Param("endDateTime") LocalDateTime endDateTime
    );

    List<Booking> findByCreatedAtBetweenOrderByCreatedAtDesc(
            LocalDateTime startDateTime,
            LocalDateTime endDateTime
    );

    @Query("""
            SELECT b.type, SUM(b.amount)
            FROM Booking b
            WHERE b.userId = :userId AND b.status = 'CONFIRMED'
            GROUP BY b.type
            """)
    List<Object[]> getBookingSummaryByUser(@Param("userId") Long userId);




    @Query(value = "SELECT COALESCE(SUM(amount), 0) FROM bookings WHERE itin_id = :itineraryId AND status = 'CONFIRMED'", nativeQuery = true)
    Double sumConfirmedAmountByItineraryId(@Param("itineraryId") Long itineraryId);

    @Query("""
            SELECT b FROM Booking b
            WHERE b.status = 'CONFIRMED'
              AND b.createdAt BETWEEN :startDateTime AND :endDateTime
            """)
    List<Booking> findConfirmedByCreatedAtBetween(
            @Param("startDateTime") LocalDateTime startDateTime,
            @Param("endDateTime") LocalDateTime endDateTime
    );

    @Query("""
            SELECT COALESCE(SUM(b.amount), 0) FROM Booking b
            WHERE b.userId = :userId
              AND b.status = 'CONFIRMED'
              AND b.createdAt BETWEEN :startDateTime AND :endDateTime
            """)
    Double sumConfirmedAmountByUserAndRange(
            @Param("userId") Long userId,
            @Param("startDateTime") LocalDateTime startDateTime,
            @Param("endDateTime") LocalDateTime endDateTime
    );

    @Query("""
            SELECT COUNT(b) FROM Booking b
            WHERE b.userId = :userId
              AND b.status = 'CONFIRMED'
              AND b.createdAt BETWEEN :startDateTime AND :endDateTime
            """)
    long countConfirmedByUserAndRange(
            @Param("userId") Long userId,
            @Param("startDateTime") LocalDateTime startDateTime,
            @Param("endDateTime") LocalDateTime endDateTime
    );

    @Query("""
            SELECT COUNT(b), COALESCE(SUM(b.amount), 0)
            FROM Booking b
            WHERE b.itineraryId = :itineraryId
              AND b.status = 'CONFIRMED'
            """)
    Object[] getConfirmedSummaryByItinerary(@Param("itineraryId") Long itineraryId);

    @Query("""
            SELECT COUNT(b), COALESCE(SUM(b.amount), 0)
            FROM Booking b
            WHERE b.itineraryId IN :itineraryIds
              AND b.createdAt BETWEEN :startDateTime AND :endDateTime
              AND (:status IS NULL OR b.status = :status)
            """)
    Object[] aggregateByItineraryIds(
            @Param("itineraryIds") List<Long> itineraryIds,
            @Param("startDateTime") LocalDateTime startDateTime,
            @Param("endDateTime") LocalDateTime endDateTime,
            @Param("status") Booking.BookingStatus status
    );
}

